diff:
--- a/rtl/alu.v
+++ b/rtl/alu.v
@@ -27,5 +27,5 @@
                 y        = diff[7:0];
                 carry    = diff[8];
-                overflow = (a[7] == b[7]) && (diff[7] != a[7]);
+                overflow = (a[7] != b[7]) && (diff[7] != a[7]);
             end
             OP_AND: y = a & b;
@@ -34,5 +34,5 @@
             OP_SLL: y = a << b[2:0];
             OP_SRL: y = a >> b[2:0];
-            OP_SLT: y = {7'd0, (a < b)};
+            OP_SLT: y = {7'd0, ($signed(a) < $signed(b))};
             default: y = 8'd0;
         endcase
